"""Derive ADSL (Subject-Level Analysis Dataset) from SDTM DM, EX and DS."""

import datetime

import numpy as np
import pandas as pd

PROVENANCE = {
    "USUBJID": ["DM.USUBJID"],
    "TRT01P": ["DM.ARM"],
    "TRT01A": ["DM.ACTARM"],
    "TRTSDT": ["EX.USUBJID", "EX.EXSTDTC", "EX.EXDOSE", "EX.EXTRT"],
    "TRTEDT": ["EX.USUBJID", "EX.EXENDTC", "EX.EXDOSE", "EX.EXTRT"],
    "TRTDURD": ["ADSL.TRTSDT", "ADSL.TRTEDT"],
    "SAFFL": ["ADSL.TRTSDT"],
    "AGEGR1": ["DM.AGE"],
    "RACEGR1": ["DM.RACE"],
    "EOSSTT": ["DS.USUBJID", "DS.DSCAT", "DS.DSDECOD"],
}


def _parse_iso_date(value):
    """Parse an ISO 8601 date/datetime string into a datetime.date.

    ASSUMPTION: no date imputation is performed. A value that does not carry a
    complete (YYYY-MM-DD) date component is treated as missing, which is the
    conservative choice for a regulated submission.
    """
    if value is None:
        return None
    if isinstance(value, float) and np.isnan(value):
        return None
    if isinstance(value, datetime.datetime):
        return value.date()
    if isinstance(value, datetime.date):
        return value
    s = str(value).strip()
    if len(s) < 10:
        return None
    try:
        return datetime.date(int(s[0:4]), int(s[5:7]), int(s[8:10]))
    except (ValueError, TypeError):
        return None


def _as_str(value):
    """Return a plain Python string; missing values become the empty string."""
    if value is None:
        return ""
    if isinstance(value, float) and np.isnan(value):
        return ""
    if value is pd.NaT:
        return ""
    return str(value)


def derive(sources):
    dm = sources["DM"].copy()
    ex = sources["EX"].copy() if "EX" in sources else pd.DataFrame(
        columns=["USUBJID", "EXSTDTC", "EXENDTC"]
    )
    ds = sources["DS"].copy() if "DS" in sources else pd.DataFrame(
        columns=["USUBJID", "DSCAT", "DSDECOD"]
    )

    # ---------------------------------------------------------------- base ---
    adsl = pd.DataFrame(
        {
            "USUBJID": dm["USUBJID"].map(_as_str),
            "TRT01P": dm["ARM"].map(_as_str),
            "TRT01A": dm["ACTARM"].map(_as_str),
        }
    )
    # ASSUMPTION: DM is already one record per subject (SDTM requirement); any
    # accidental duplicate is collapsed keeping the first occurrence.
    adsl = adsl.drop_duplicates(subset=["USUBJID"], keep="first")

    # ------------------------------------------------- treatment start/end ---
    # ALL exposure records are used: EXDOSE == 0 (placebo) is valid exposure.
    ex_dates = pd.DataFrame(
        {
            "USUBJID": ex["USUBJID"].map(_as_str) if len(ex) else pd.Series(dtype=object),
            "STDT": ex["EXSTDTC"].map(_parse_iso_date) if len(ex) else pd.Series(dtype=object),
            "ENDT": ex["EXENDTC"].map(_parse_iso_date) if len(ex) else pd.Series(dtype=object),
        }
    )

    first_dose, last_dose = {}, {}
    for usubjid, grp in ex_dates.groupby("USUBJID", sort=False):
        st = [d for d in grp["STDT"] if d is not None]
        en = [d for d in grp["ENDT"] if d is not None]
        if st:
            first_dose[usubjid] = min(st)
        if en:
            last_dose[usubjid] = max(en)

    adsl["TRTSDT"] = [first_dose.get(u) for u in adsl["USUBJID"]]
    adsl["TRTEDT"] = [last_dose.get(u) for u in adsl["USUBJID"]]

    # -------------------------------------------------------------- TRTDURD --
    durd = []
    for sdt, edt in zip(adsl["TRTSDT"], adsl["TRTEDT"]):
        if sdt is None or edt is None:
            durd.append(np.nan)
        else:
            durd.append(float((edt - sdt).days + 1))
    adsl["TRTDURD"] = durd

    # ---------------------------------------------------------------- SAFFL --
    adsl["SAFFL"] = ["Y" if sdt is not None else "N" for sdt in adsl["TRTSDT"]]

    # --------------------------------------------------------------- AGEGR1 --
    # ASSUMPTION: a missing AGE cannot be grouped and yields an empty string.
    age = pd.to_numeric(dm.set_index(dm["USUBJID"].map(_as_str))["AGE"], errors="coerce")
    age = age[~age.index.duplicated(keep="first")]

    def _agegr1(u):
        a = age.get(u, np.nan)
        if pd.isna(a):
            return ""
        return "18-64" if a <= 64 else ">64"

    adsl["AGEGR1"] = [_agegr1(u) for u in adsl["USUBJID"]]

    # -------------------------------------------------------------- RACEGR1 --
    race = dm.set_index(dm["USUBJID"].map(_as_str))["RACE"].map(_as_str)
    race = race[~race.index.duplicated(keep="first")]
    adsl["RACEGR1"] = [
        "White" if race.get(u, "").strip().upper() == "WHITE" else "Non-white"
        for u in adsl["USUBJID"]
    ]

    # --------------------------------------------------------------- EOSSTT --
    # ASSUMPTION: when a subject has more than one DISPOSITION EVENT record the
    # first one by DSSEQ (record order otherwise) is used.
    if len(ds):
        disp = ds.copy()
        disp["USUBJID"] = disp["USUBJID"].map(_as_str)
        disp["DSCAT"] = disp["DSCAT"].map(_as_str)
        disp["DSDECOD"] = disp["DSDECOD"].map(_as_str)
        disp = disp[disp["DSCAT"].str.strip().str.upper() == "DISPOSITION EVENT"]
        if "DSSEQ" in disp.columns:
            disp = disp.sort_values(["USUBJID", "DSSEQ"], kind="mergesort")
        disp = disp.drop_duplicates(subset=["USUBJID"], keep="first")
        decod_map = dict(zip(disp["USUBJID"], disp["DSDECOD"]))
    else:
        decod_map = {}

    def _eosstt(u):
        # ASSUMPTION: no disposition event record -> status not derivable -> "".
        if u not in decod_map:
            return ""
        d = decod_map[u].strip().upper()
        if d == "COMPLETED":
            return "COMPLETED"
        if d == "SCREEN FAILURE":
            return ""
        if d == "":
            return ""
        return "DISCONTINUED"

    adsl["EOSSTT"] = [_eosstt(u) for u in adsl["USUBJID"]]

    # ---------------------------------------------------------------- final --
    adsl = adsl[
        [
            "USUBJID",
            "TRT01P",
            "TRT01A",
            "TRTSDT",
            "TRTEDT",
            "TRTDURD",
            "SAFFL",
            "AGEGR1",
            "RACEGR1",
            "EOSSTT",
        ]
    ]
    adsl["TRTSDT"] = adsl["TRTSDT"].astype(object)
    adsl["TRTEDT"] = adsl["TRTEDT"].astype(object)
    adsl["TRTDURD"] = adsl["TRTDURD"].astype(float)

    return adsl.sort_values("USUBJID", kind="mergesort").reset_index(drop=True)

"""Derive ADAE (Adverse Event Analysis Dataset) from SDTM AE and derived ADSL.

Structure: one record per adverse event per subject (key: USUBJID, AESEQ).
"""

import calendar
import datetime

import numpy as np
import pandas as pd

# ---------------------------------------------------------------------------
# ADSL variables carried through unchanged (all ADSL variables; USUBJID is the
# merge key and is also retained).
# ---------------------------------------------------------------------------
ADSL_VARS = [
    "STUDYID", "USUBJID", "SUBJID", "SITEID", "COUNTRY", "RFSTDTC", "RFENDTC",
    "RFXSTDTC", "RFXENDTC", "RFPENDTC", "SCRFDT", "FRVDT", "DTHDTC", "DTHADY",
    "DTHFL", "LDDTHELD", "LDDTHGR1", "DTH30FL", "DTHA30FL", "DTHDOM",
    "DTHB30FL", "REGION1", "DMDTC", "DMDY", "AGE", "AGEU", "AGEGR1", "SEX",
    "RACE", "RACEGR1", "ETHNIC", "SAFFL", "ARM", "ARMCD", "ACTARM", "ACTARMCD",
    "TRT01P", "TRT01A", "TRTSDT", "TRTSDTM", "TRTSTMF", "TRTEDT", "TRTEDTM",
    "TRTETMF", "EOSSTT", "EOSDT", "RFICDTC", "RANDDT", "LSTALVDT", "TRTDURD",
    "DTHDT", "DTHDTF", "DTHCAUS", "DTHCGR1", "BRTHDTC",
]

ADSL_DATE_VARS = ["SCRFDT", "FRVDT", "TRTSDT", "TRTEDT", "EOSDT", "RANDDT",
                  "LSTALVDT", "DTHDT"]
ADSL_DTM_VARS = ["TRTSDTM", "TRTEDTM"]
ADSL_NUM_VARS = ["DTHADY", "LDDTHELD", "DMDY", "AGE", "TRTDURD"]

NEW_VARS = ["AESEQ", "ASTDT", "ASTDTF", "AENDT", "AENDTF", "ASTDY", "AENDY",
            "ADURN", "TRTEMFL", "AOCCIFL", "ASEV", "ASEVN"]

# ---------------------------------------------------------------------------
# Provenance: every produced variable -> list of contributing source columns
# ---------------------------------------------------------------------------
PROVENANCE = {v: ["ADSL." + v] for v in ADSL_VARS}
PROVENANCE["USUBJID"] = ["AE.USUBJID", "ADSL.USUBJID"]
PROVENANCE.update({
    "AESEQ": ["AE.AESEQ"],
    "ASTDT": ["AE.AESTDTC"],
    "ASTDTF": ["AE.AESTDTC"],
    "AENDT": ["AE.AEENDTC"],
    "AENDTF": ["AE.AEENDTC"],
    "ASTDY": ["ADAE.ASTDT", "ADSL.TRTSDT"],
    "AENDY": ["ADAE.AENDT", "ADSL.TRTSDT"],
    "ADURN": ["ADAE.ASTDT", "ADAE.AENDT"],
    "TRTEMFL": ["ADAE.ASTDT", "ADSL.TRTSDT", "ADSL.TRTEDT"],
    "AOCCIFL": ["ADAE.USUBJID", "ADAE.ASEVN", "ADAE.ASTDT", "ADAE.AESEQ",
                "ADAE.TRTEMFL"],
    "ASEV": ["AE.AESEV"],
    "ASEVN": ["ADAE.ASEV"],
})

# ASSUMPTION: severity is collected on the standard 3-point CDISC scale.
_SEV_MAP = {"MILD": 1.0, "MODERATE": 2.0, "SEVERE": 3.0}

_MISSING_STR = {"", "NAN", "NAT", "NONE", "NA", "."}


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------
def _is_missing(v):
    if v is None or v is pd.NaT:
        return True
    try:
        if isinstance(v, float) and np.isnan(v):
            return True
    except Exception:
        pass
    if isinstance(v, str) and v.strip().upper() in _MISSING_STR:
        return True
    return False


def _to_date(v):
    """Coerce any supported representation to a datetime.date (or None)."""
    if _is_missing(v):
        return None
    if isinstance(v, pd.Timestamp):
        return v.date()
    if isinstance(v, datetime.datetime):
        return v.date()
    if isinstance(v, datetime.date):
        return v
    s = str(v).strip()[:10]
    try:
        return pd.Timestamp(s).date()
    except Exception:
        return None


def _to_str(v):
    """Coerce to a Python string; missing becomes an empty string (blank)."""
    if _is_missing(v):
        return ""
    if isinstance(v, str):
        return v.strip()
    return str(v)


def _to_num(v):
    if _is_missing(v):
        return np.nan
    try:
        return float(v)
    except Exception:
        return np.nan


def _dtc_parts(dtc):
    """Return (year, month, day) from an ISO 8601 date/time string.

    Components that are absent or unknown ('-') are returned as None.
    """
    if _is_missing(dtc):
        return (None, None, None)
    s = str(dtc).strip().split("T")[0]
    if not s:
        return (None, None, None)
    bits = s.split("-")
    out = []
    for i in range(3):
        tok = bits[i].strip() if i < len(bits) else ""
        if tok == "" or not tok.isdigit():
            out.append(None)
        else:
            out.append(int(tok))
    return tuple(out)


def _impute_start(dtc):
    """Analysis start date + imputation flag.

    Partial dates are imputed to the earliest possible date (first of month /
    first of January).  Flag: 'D' day imputed, 'M' month (and day) imputed,
    'Y' year imputed.  ASSUMPTION: a missing year cannot be imputed, so the
    date stays missing and no flag is set.
    """
    y, m, d = _dtc_parts(dtc)
    if y is None:
        return (None, "")
    if m is None:
        return (datetime.date(y, 1, 1), "M")
    if d is None:
        return (datetime.date(y, m, 1), "D")
    try:
        return (datetime.date(y, m, d), "")
    except ValueError:
        return (None, "")


def _impute_end(dtc):
    """Analysis end date + imputation flag.

    Partial dates are imputed to the latest possible date (last day of month /
    31 December).
    """
    y, m, d = _dtc_parts(dtc)
    if y is None:
        return (None, "")
    if m is None:
        return (datetime.date(y, 12, 31), "M")
    if d is None:
        return (datetime.date(y, m, calendar.monthrange(y, m)[1]), "D")
    try:
        return (datetime.date(y, m, d), "")
    except ValueError:
        return (None, "")


def _study_day(adt, trtsdt):
    """Relative day using the ADaM convention (no day 0)."""
    if adt is None or trtsdt is None:
        return np.nan
    diff = (adt - trtsdt).days
    return float(diff + 1) if diff >= 0 else float(diff)


# ---------------------------------------------------------------------------
# Main derivation
# ---------------------------------------------------------------------------
def derive(sources):
    ae = sources["AE"].copy()
    adsl = sources["ADSL"].copy()

    # --- ADSL: normalise types, one record per subject ---------------------
    adsl = adsl[[c for c in ADSL_VARS if c in adsl.columns]].copy()
    for c in ADSL_VARS:
        if c not in adsl.columns:
            adsl[c] = np.nan
    adsl["USUBJID"] = adsl["USUBJID"].map(_to_str)
    adsl = adsl.drop_duplicates(subset=["USUBJID"], keep="first")

    for c in ADSL_DATE_VARS:
        adsl[c] = adsl[c].map(_to_date).astype(object)
    for c in ADSL_DTM_VARS:
        adsl[c] = pd.to_datetime(adsl[c], errors="coerce")
    for c in ADSL_NUM_VARS:
        adsl[c] = adsl[c].map(_to_num).astype(float)
    for c in ADSL_VARS:
        if c not in ADSL_DATE_VARS + ADSL_DTM_VARS + ADSL_NUM_VARS:
            adsl[c] = adsl[c].map(_to_str).astype(object)

    # --- AE: analysis variables -------------------------------------------
    ae["USUBJID"] = ae["USUBJID"].map(_to_str)
    df = ae[["USUBJID"]].copy()
    df["AESEQ"] = ae["AESEQ"].map(_to_num).astype(float)

    st = ae["AESTDTC"].map(_impute_start) if "AESTDTC" in ae.columns \
        else pd.Series([(None, "")] * len(ae), index=ae.index)
    en = ae["AEENDTC"].map(_impute_end) if "AEENDTC" in ae.columns \
        else pd.Series([(None, "")] * len(ae), index=ae.index)
    df["ASTDT"] = [t[0] for t in st]
    df["ASTDTF"] = [t[1] for t in st]
    df["AENDT"] = [t[0] for t in en]
    df["AENDTF"] = [t[1] for t in en]

    df["ASEV"] = ae["AESEV"].map(_to_str).astype(object)
    df["ASEVN"] = df["ASEV"].map(lambda s: _SEV_MAP.get(s.upper(), np.nan)).astype(float)

    # --- Merge ADSL (all ADSL values carried unchanged) --------------------
    out = df.merge(adsl, on="USUBJID", how="left", validate="many_to_one")

    # --- Timing variables requiring ADSL treatment dates -------------------
    out["ASTDY"] = [_study_day(a, t) for a, t in zip(out["ASTDT"], out["TRTSDT"])]
    out["AENDY"] = [_study_day(a, t) for a, t in zip(out["AENDT"], out["TRTSDT"])]
    out["ADURN"] = [
        float((e - s).days + 1) if (s is not None and e is not None and e >= s)
        else np.nan
        for s, e in zip(out["ASTDT"], out["AENDT"])
    ]

    # ASSUMPTION: an event is treatment emergent when its (imputed) analysis
    # start date is on or after first dose and on or before last dose (no
    # post-treatment window added).  Subjects with no treatment start date
    # (untreated) have no treatment-emergent events.  Non-emergent records
    # carry a blank flag.
    trtemfl = []
    for a, s, e in zip(out["ASTDT"], out["TRTSDT"], out["TRTEDT"]):
        if a is None or s is None:
            trtemfl.append("")
        elif a >= s and (e is None or a <= e):
            trtemfl.append("Y")
        else:
            trtemfl.append("")
    out["TRTEMFL"] = trtemfl

    # --- AOCCIFL: first most-severe treatment-emergent event per subject ---
    # ASSUMPTION: ordering is highest ASEVN, then earliest ASTDT, then lowest
    # AESEQ; records with unknown severity/start date sort last.  Only the
    # selected record is flagged 'Y'; all other records are blank.
    out["AOCCIFL"] = ""
    elig = out[out["TRTEMFL"] == "Y"].copy()
    if len(elig):
        elig["_sevn"] = elig["ASEVN"].fillna(-np.inf)
        elig["_astd"] = elig["ASTDT"].map(
            lambda d: d if d is not None else datetime.date(9999, 12, 31))
        elig["_seq"] = elig["AESEQ"].fillna(np.inf)
        elig = elig.sort_values(
            ["USUBJID", "_sevn", "_astd", "_seq"],
            ascending=[True, False, True, True], kind="mergesort")
        first_idx = elig.groupby("USUBJID", sort=False).head(1).index
        out.loc[first_idx, "AOCCIFL"] = "Y"

    # --- Final structure ---------------------------------------------------
    out = out.sort_values(["USUBJID", "AESEQ"], kind="mergesort").reset_index(drop=True)

    ordered = ADSL_VARS + [v for v in NEW_VARS if v not in ADSL_VARS]
    out = out[ordered]

    for c in ["ASTDT", "AENDT"]:
        out[c] = out[c].astype(object)
    for c in ["ASTDTF", "AENDTF", "TRTEMFL", "AOCCIFL", "ASEV"]:
        out[c] = out[c].map(_to_str).astype(object)
    for c in ["AESEQ", "ASTDY", "AENDY", "ADURN", "ASEVN"]:
        out[c] = out[c].astype(float)

    return out

"""
ADAE - Adverse Event Analysis Dataset
Derived from SDTM AE and the derived ADSL dataset.

Structure: one record per adverse event per subject (key: USUBJID, AESEQ).
"""

import calendar
import datetime

import numpy as np
import pandas as pd

# ASSUMPTION: USUBJID is retained because the specification declares it as part of
# the dataset key (USUBJID, AESEQ); without it the records cannot be attributed to
# a subject. No other variables beyond the specified list are produced.
PROVENANCE = {
    "USUBJID": ["AE.USUBJID"],
    "AESEQ": ["AE.AESEQ"],
    "ASTDT": ["AE.AESTDTC"],
    "ASTDTF": ["AE.AESTDTC"],
    "AENDT": ["AE.AEENDTC"],
    "AENDTF": ["AE.AEENDTC"],
    "ASTDY": ["AE.AESTDTC", "ADSL.TRTSDT"],
    "AENDY": ["AE.AEENDTC", "ADSL.TRTSDT"],
    "ADURN": ["AE.AESTDTC", "AE.AEENDTC"],
    "TRTEMFL": ["AE.AESTDTC", "ADSL.TRTSDT"],
    "AOCCIFL": ["AE.AESEV", "AE.AESTDTC", "AE.AESEQ", "ADSL.TRTSDT"],
    "ASEV": ["AE.AESEV"],
    "ASEVN": ["AE.AESEV"],
}

# ASSUMPTION: Severity is collected using the standard MILD/MODERATE/SEVERE scale,
# numerically coded 1/2/3 for ASEVN and for the maximum-severity selection.
_SEV_MAP = {"MILD": 1.0, "MODERATE": 2.0, "SEVERE": 3.0}


def _dtc_parts(value):
    """Return (year, month, day) from an ISO 8601 (possibly partial) date/time string."""
    if value is None:
        return (None, None, None)
    if isinstance(value, float) and np.isnan(value):
        return (None, None, None)
    if value is pd.NaT:
        return (None, None, None)
    if isinstance(value, (datetime.datetime, pd.Timestamp)):
        return (value.year, value.month, value.day)
    if isinstance(value, datetime.date):
        return (value.year, value.month, value.day)
    s = str(value).strip()
    if s == "" or s.lower() in ("nan", "nat", "none"):
        return (None, None, None)
    s = s.split("T")[0]
    parts = s.split("-")
    year = month = day = None
    if len(parts) >= 1 and parts[0].isdigit() and len(parts[0]) == 4:
        year = int(parts[0])
    if year is None:
        # ASSUMPTION: a date string without a usable 4-digit year yields no analysis date.
        return (None, None, None)
    if len(parts) >= 2 and parts[1].isdigit() and 1 <= int(parts[1]) <= 12:
        month = int(parts[1])
    if month is None:
        return (year, None, None)
    if len(parts) >= 3 and parts[2].isdigit() and 1 <= int(parts[2]) <= 31:
        day = int(parts[2])
    return (year, month, day)


def _impute_start(value):
    """Impute a partial AE start date to the earliest possible date.

    Imputation flag follows ADaM convention: 'D' = day imputed,
    'M' = month (and day) imputed, '' = nothing imputed.
    """
    year, month, day = _dtc_parts(value)
    if year is None:
        # Year unknown -> no date can be derived; flag left blank.
        return (None, "")
    if month is None:
        return (datetime.date(year, 1, 1), "M")
    if day is None:
        return (datetime.date(year, month, 1), "D")
    try:
        return (datetime.date(year, month, day), "")
    except ValueError:
        return (None, "")


def _impute_end(value):
    """Impute a partial AE end date to the latest possible date."""
    year, month, day = _dtc_parts(value)
    if year is None:
        return (None, "")
    if month is None:
        return (datetime.date(year, 12, 31), "M")
    if day is None:
        return (datetime.date(year, month, calendar.monthrange(year, month)[1]), "D")
    try:
        return (datetime.date(year, month, day), "")
    except ValueError:
        return (None, "")


def _to_date(value):
    """Normalise an ADSL date value to datetime.date (or None)."""
    if value is None or value is pd.NaT:
        return None
    if isinstance(value, float) and np.isnan(value):
        return None
    if isinstance(value, (datetime.datetime, pd.Timestamp)):
        return value.date()
    if isinstance(value, datetime.date):
        return value
    ts = pd.to_datetime(value, errors="coerce")
    if ts is pd.NaT or pd.isna(ts):
        return None
    return ts.date()


def _relative_day(adt, trtsdt):
    """ADaM relative study day: no day 0; days before treatment start are negative."""
    if adt is None or trtsdt is None:
        return np.nan
    delta = (adt - trtsdt).days
    return float(delta + 1) if delta >= 0 else float(delta)


def derive(sources):
    ae = sources["AE"].copy()
    adsl = sources["ADSL"].copy()

    adsl_sub = adsl[["USUBJID", "TRTSDT"]].drop_duplicates(subset=["USUBJID"])
    adsl_sub = adsl_sub.assign(_TRTSDT=adsl_sub["TRTSDT"].map(_to_date))

    df = ae.merge(adsl_sub[["USUBJID", "_TRTSDT"]], on="USUBJID", how="left")

    # ---- Analysis dates and imputation flags -------------------------------
    start = df["AESTDTC"].map(_impute_start) if "AESTDTC" in df.columns else pd.Series(
        [(None, "")] * len(df), index=df.index
    )
    end = df["AEENDTC"].map(_impute_end) if "AEENDTC" in df.columns else pd.Series(
        [(None, "")] * len(df), index=df.index
    )

    df["ASTDT"] = [s[0] for s in start]
    df["ASTDTF"] = [str(s[1]) for s in start]
    df["AENDT"] = [e[0] for e in end]
    df["AENDTF"] = [str(e[1]) for e in end]

    # ---- Relative days and duration ---------------------------------------
    df["ASTDY"] = [
        _relative_day(a, t) for a, t in zip(df["ASTDT"], df["_TRTSDT"])
    ]
    df["AENDY"] = [
        _relative_day(a, t) for a, t in zip(df["AENDT"], df["_TRTSDT"])
    ]
    # ASSUMPTION: ADURN = AENDT - ASTDT + 1 (inclusive of both days), derived only
    # when both analysis dates are available.
    df["ADURN"] = [
        float((e - s).days + 1) if (s is not None and e is not None) else np.nan
        for s, e in zip(df["ASTDT"], df["AENDT"])
    ]

    # ---- Treatment emergent flag ------------------------------------------
    # ASSUMPTION: an event is treatment emergent if the subject was treated and the
    # (imputed) analysis start date is on or after the first dose date. If the start
    # date cannot be derived at all for a treated subject, the event is flagged as
    # treatment emergent (conservative for safety reporting). Untreated subjects
    # have no treatment emergent events.
    trtemfl = []
    for astdt, trtsdt in zip(df["ASTDT"], df["_TRTSDT"]):
        if trtsdt is None:
            trtemfl.append("")
        elif astdt is None:
            trtemfl.append("Y")
        elif astdt >= trtsdt:
            trtemfl.append("Y")
        else:
            trtemfl.append("")
    df["TRTEMFL"] = trtemfl

    # ---- Analysis severity -------------------------------------------------
    if "AESEV" in df.columns:
        sev = df["AESEV"].map(lambda v: "" if (v is None or pd.isna(v)) else str(v).strip())
    else:
        sev = pd.Series([""] * len(df), index=df.index)
    df["ASEV"] = sev
    df["ASEVN"] = sev.str.upper().map(_SEV_MAP).astype(float)

    # ---- First occurrence of maximum severity ------------------------------
    # ASSUMPTION: AOCCIFL flags, within each subject, the single treatment emergent
    # record with the highest analysis severity; ties are broken by the earliest
    # analysis start date and then the lowest AESEQ. Records with unknown severity
    # are not eligible for the flag.
    df["AESEQ"] = pd.to_numeric(df["AESEQ"], errors="coerce").astype(float)
    df["AOCCIFL"] = ""

    cand = df[(df["TRTEMFL"] == "Y") & df["ASEVN"].notna()].copy()
    if len(cand):
        cand["_sortdt"] = [
            pd.Timestamp(d) if d is not None else pd.Timestamp.max
            for d in cand["ASTDT"]
        ]
        cand = cand.sort_values(
            by=["USUBJID", "ASEVN", "_sortdt", "AESEQ"],
            ascending=[True, False, True, True],
            kind="mergesort",
        )
        first_idx = cand.groupby("USUBJID", sort=False).head(1).index
        df.loc[first_idx, "AOCCIFL"] = "Y"

    # ---- Final structure ---------------------------------------------------
    out_cols = [
        "USUBJID",
        "AESEQ",
        "ASTDT",
        "ASTDTF",
        "AENDT",
        "AENDTF",
        "ASTDY",
        "AENDY",
        "ADURN",
        "TRTEMFL",
        "AOCCIFL",
        "ASEV",
        "ASEVN",
    ]
    out = df[out_cols].copy()

    out["USUBJID"] = out["USUBJID"].astype(str)
    for c in ("ASTDTF", "AENDTF", "TRTEMFL", "AOCCIFL", "ASEV"):
        out[c] = out[c].fillna("").astype(str)
    for c in ("AESEQ", "ASTDY", "AENDY", "ADURN", "ASEVN"):
        out[c] = pd.to_numeric(out[c], errors="coerce").astype(float)
    for c in ("ASTDT", "AENDT"):
        out[c] = out[c].map(lambda v: v if isinstance(v, datetime.date) else None).astype(object)

    out = out.sort_values(by=["USUBJID", "AESEQ"], kind="mergesort").reset_index(drop=True)
    return out

"""
ADAE - Adverse Event Analysis Dataset
One record per adverse event per subject (key: USUBJID, AESEQ).
"""

import calendar
import datetime as dt

import numpy as np
import pandas as pd

# ASSUMPTION: USUBJID is named in the specification as part of the dataset key and is
# required to uniquely identify records, so it is carried on the output as a key
# variable.  No other variables beyond the specification list are produced.
PROVENANCE = {
    "USUBJID": ["AE.USUBJID"],
    "AESEQ": ["AE.AESEQ"],
    "ASTDT": ["AE.AESTDTC"],
    "ASTDTF": ["AE.AESTDTC"],
    "AENDT": ["AE.AEENDTC"],
    "AENDTF": ["AE.AEENDTC"],
    "ASTDY": ["AE.AESTDTC", "ADSL.TRTSDT"],
    "AENDY": ["AE.AEENDTC", "ADSL.TRTSDT"],
    "ADURN": ["AE.AESTDTC", "AE.AEENDTC"],
    "TRTEMFL": ["AE.AESTDTC", "ADSL.TRTSDT", "ADSL.TRTEDT"],
    "AOCCIFL": [
        "AE.AESEV",
        "AE.AESTDTC",
        "AE.AESEQ",
        "ADSL.TRTSDT",
        "ADSL.TRTEDT",
        "ADSL.SAFFL",
    ],
    "ASEV": ["AE.AESEV"],
    "ASEVN": ["AE.AESEV"],
}

# ASSUMPTION: Severity is collected using the standard MILD/MODERATE/SEVERE scale;
# any other (or missing) value yields a missing ASEVN.
_SEV_MAP = {"MILD": 1.0, "MODERATE": 2.0, "SEVERE": 3.0}

# ASSUMPTION: Treatment-emergent window = onset on or after first dose through
# 30 days after last dose (inclusive).  If last dose date is missing, any onset on
# or after first dose is treatment emergent.
_TE_WINDOW_DAYS = 30


def _split_dtc(value):
    """Return (year, month, day) integer components of an ISO 8601 date/time string.

    Missing / non-numeric components are returned as None.
    """
    if value is None:
        return (None, None, None)
    if isinstance(value, float) and np.isnan(value):
        return (None, None, None)
    try:
        if pd.isna(value):
            return (None, None, None)
    except (TypeError, ValueError):
        pass
    s = str(value).strip()
    if s == "":
        return (None, None, None)
    s = s.split("T")[0]
    parts = s.split("-")
    comps = []
    for i in range(3):
        tok = parts[i].strip() if i < len(parts) else ""
        if tok == "" or not tok.isdigit():
            comps.append(None)
        else:
            comps.append(int(tok))
    return tuple(comps)


def _impute_date(value, end=False):
    """Impute a partial ISO date.

    Start dates: missing day -> first of month, missing month -> 01 January.
    End dates:   missing day -> last of month, missing month -> 31 December.
    A missing year cannot be imputed -> date is missing, flag is blank.

    Returns (datetime.date or None, imputation flag string).
    """
    y, m, d = _split_dtc(value)
    if y is None:
        # ASSUMPTION: With no year available no defensible imputation exists;
        # the analysis date is left missing and the flag is left blank.
        return (None, "")
    if m is None:
        month = 12 if end else 1
        day = 31 if end else 1
        return (dt.date(y, month, day), "M")
    if d is None:
        day = calendar.monthrange(y, m)[1] if end else 1
        return (dt.date(y, m, day), "D")
    try:
        return (dt.date(y, m, d), "")
    except ValueError:
        return (None, "")


def _as_ts(date_obj):
    if date_obj is None:
        return pd.NaT
    return pd.Timestamp(date_obj)


def _study_day(adt, trtsdt):
    """ADaM relative day: no day 0 (day 1 is the first treatment day)."""
    if adt is None or trtsdt is None:
        return np.nan
    delta = (adt - trtsdt).days
    return float(delta + 1) if delta >= 0 else float(delta)


def derive(sources):
    ae = sources["AE"].copy()
    adsl = sources["ADSL"].copy()

    # ---- ADSL treatment dates / safety flag ---------------------------------
    def _to_date(v):
        if v is None:
            return None
        if isinstance(v, dt.datetime):
            return v.date()
        if isinstance(v, dt.date):
            return v
        try:
            if pd.isna(v):
                return None
        except (TypeError, ValueError):
            return None
        ts = pd.to_datetime(v, errors="coerce")
        return None if pd.isna(ts) else ts.date()

    adsl_sub = adsl[["USUBJID", "TRTSDT", "TRTEDT", "SAFFL"]].copy()
    adsl_sub["TRTSDT"] = adsl_sub["TRTSDT"].map(_to_date)
    adsl_sub["TRTEDT"] = adsl_sub["TRTEDT"].map(_to_date)
    adsl_sub["SAFFL"] = adsl_sub["SAFFL"].map(
        lambda v: "" if v is None or (isinstance(v, float) and np.isnan(v)) else str(v)
    )
    # ASSUMPTION: ADSL is one record per subject, so the merge cannot multiply AE rows.
    adsl_sub = adsl_sub.drop_duplicates(subset=["USUBJID"], keep="first")

    df = ae[["USUBJID", "AESEQ", "AESTDTC", "AEENDTC", "AESEV"]].copy()
    df = df.merge(adsl_sub, on="USUBJID", how="left")

    # ---- Keys ---------------------------------------------------------------
    df["USUBJID"] = df["USUBJID"].astype(str)
    df["AESEQ"] = pd.to_numeric(df["AESEQ"], errors="coerce").astype(float)

    # ---- Analysis dates and imputation flags --------------------------------
    st = df["AESTDTC"].map(lambda v: _impute_date(v, end=False))
    en = df["AEENDTC"].map(lambda v: _impute_date(v, end=True))
    df["ASTDT"] = [x[0] for x in st]
    df["ASTDTF"] = [x[1] for x in st]
    df["AENDT"] = [x[0] for x in en]
    df["AENDTF"] = [x[1] for x in en]

    # ---- Relative days ------------------------------------------------------
    df["ASTDY"] = [
        _study_day(a, t) for a, t in zip(df["ASTDT"], df["TRTSDT"])
    ]
    df["AENDY"] = [
        _study_day(a, t) for a, t in zip(df["AENDT"], df["TRTSDT"])
    ]

    # ---- Duration -----------------------------------------------------------
    # ASSUMPTION: ADURN = AENDT - ASTDT + 1 (days, inclusive of both endpoints);
    # missing when either analysis date is missing.
    dur = []
    for a, b in zip(df["ASTDT"], df["AENDT"]):
        if a is None or b is None:
            dur.append(np.nan)
        else:
            dur.append(float((b - a).days + 1))
    df["ADURN"] = dur

    # ---- Treatment emergent flag -------------------------------------------
    te = []
    for a, ts, te_dt in zip(df["ASTDT"], df["TRTSDT"], df["TRTEDT"]):
        if a is None or ts is None:
            # ASSUMPTION: Events with an unknown onset date or in untreated subjects
            # are not flagged as treatment emergent.
            te.append("")
        elif a < ts:
            te.append("")
        elif te_dt is not None and a > te_dt + dt.timedelta(days=_TE_WINDOW_DAYS):
            te.append("")
        else:
            te.append("Y")
    df["TRTEMFL"] = te

    # ---- Severity -----------------------------------------------------------
    def _sev(v):
        if v is None:
            return ""
        if isinstance(v, float) and np.isnan(v):
            return ""
        try:
            if pd.isna(v):
                return ""
        except (TypeError, ValueError):
            pass
        return str(v).strip()

    df["ASEV"] = df["AESEV"].map(_sev)
    df["ASEVN"] = df["ASEV"].map(lambda v: _SEV_MAP.get(v.upper(), np.nan))

    # ---- First maximum severity occurrence flag -----------------------------
    # ASSUMPTION: AOCCIFL flags, within the safety population, the chronologically
    # first treatment-emergent event having the subject's maximum severity;
    # ties are broken by earliest analysis start date then lowest AESEQ.
    df["AOCCIFL"] = ""
    elig = (df["TRTEMFL"] == "Y") & (df["SAFFL"].str.upper() == "Y") & df["ASEVN"].notna()
    if elig.any():
        tmp = df.loc[elig].copy()
        tmp["_sortdt"] = [
            _as_ts(a) if a is not None else pd.Timestamp("2262-01-01")
            for a in tmp["ASTDT"]
        ]
        tmp = tmp.sort_values(
            ["USUBJID", "ASEVN", "_sortdt", "AESEQ"],
            ascending=[True, False, True, True],
            kind="mergesort",
        )
        first_idx = tmp.groupby("USUBJID", sort=False).head(1).index
        df.loc[first_idx, "AOCCIFL"] = "Y"

    # ---- Final structure ----------------------------------------------------
    out = df.sort_values(["USUBJID", "AESEQ"], kind="mergesort").reset_index(drop=True)

    out["ASTDT"] = out["ASTDT"].map(lambda v: v if isinstance(v, dt.date) else None)
    out["AENDT"] = out["AENDT"].map(lambda v: v if isinstance(v, dt.date) else None)
    for c in ["ASTDTF", "AENDTF", "TRTEMFL", "AOCCIFL", "ASEV"]:
        out[c] = out[c].fillna("").astype(str)

    cols = [
        "USUBJID",
        "AESEQ",
        "ASTDT",
        "ASTDTF",
        "AENDT",
        "AENDTF",
        "ASTDY",
        "AENDY",
        "ADURN",
        "TRTEMFL",
        "AOCCIFL",
        "ASEV",
        "ASEVN",
    ]
    out = out[cols]
    out["ASTDT"] = out["ASTDT"].astype(object)
    out["AENDT"] = out["AENDT"].astype(object)
    return out
